-- Shrewsbury MA and Tulsa OK: one group each with many sessions, published with intros; Mt. Pleasant SC is folded into Charleston's area page.
UPDATE "City" SET "published" = 1, "intro" = 'Shrewsbury has one regular game: Lets Bam Mahjong holds Sunday social play at the First Congregational Church, with a guided table for players who want help and a plain table for those who know the American rules. The group also offers Beginner Mahjong Lessons covering sessions 101 and 102, separate from the open play. Tickets are sold in advance, so check the listing for the next date. If you are new, start with the beginner lessons, then join a Sunday guided table.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'shrewsbury-ma';
UPDATE "City" SET "published" = 1, "intro" = 'Tulsa''s regular game is Mahjongg Tulsa, a Meetup group that plays the American version on Mondays, Wednesdays and Fridays at noon at the Barnes & Noble in the Southroads shopping center. It is for experienced players, and the group does not teach. Bring a 2026 card and $4 for the table, and join the Meetup group to see the next date. If you are still learning, practice the basics with a friend or in a class first, then join a table.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'tulsa';
UPDATE "City" SET "areaId" = (SELECT id FROM "City" WHERE "slug" = 'charleston'), "published" = 0, "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'mt-pleasant';
